    <section class="route-detail-card route-options">${recorded?recordedPathHTML(profile):`<h2>Choose the short or full version</h2><p>Only enabled optional stops appear in the path and estimate. Leave them out when the lane or team needs you.</p>${allOptional.length?allOptional.map(s=>`<label><input type="checkbox" data-route-option="${esc(s.id)}" ${selectedOptions().includes(s.id)?'checked':''}><span>${esc(s.label)}<small>${s.firstSeconds?'First spawn '+formatClock(s.firstSeconds)+' · ':''}${esc(s.kind==='utility'?'Utility stop; no soul reward counted':s.skip)}</small></span></label>`).join(''):'<p class="source-note">This plan uses a fixed sequence. Choose another plan to change its purpose.</p>'}<label><input type="checkbox" id="include-waves" ${state.waves?'checked':''}><span>Include ${value.waveCount} starting / destination solo wave${value.waveCount===1?'':'s'}<small>Same-lane revisits never add a second wave.</small></span></label>`}</section>
