  function renderCatalog(){const container=$('route-catalog-grid'),profiles=registry.profiles.filter(p=>state.catalogSide==='ALL'||Object.hasOwn(p.variants,state.catalogSide));$('route-side').value=state.catalogSide;container.innerHTML=profiles.map(p=>{const side=sideFor(p.id,state.catalogSide);return`<button class="route-plan-card" data-route-profile="${esc(p.id)}" aria-pressed="${p.id===state.profile}" aria-label="${esc(p.title)} · ${teamName(side)}"><span class="route-choice-icon">${icon(p.shape==='return'?'rotate':p.shape==='team'?'fit':'route')}</span><span class="route-choice-copy"><strong>${esc(p.title)}</strong><small>${teamName(side)} · ${esc(p.startLabel)}</small><span>${p.evidence?`${esc(p.evidence.author)} · ${esc(practiceLabel(p))}`:esc(routeShape(p))}</span></span>${icon('right')}</button>`;}).join('')||'<p class="source-note">No recorded routes are available for this team.</p>';}
