  function renderClockValues(){if(!registry||!data)return;const value=routeValue(),status=routeStatus();document.querySelectorAll('[data-route-value]').forEach(n=>n.textContent=value.verified===false?'Inventory not verified':n.dataset.routeValue==='buffs'?'~'+value.buffs:fmt(value[n.dataset.routeValue]||0));document.querySelectorAll('[data-route-start-status]').forEach(n=>n.textContent=status.text);const card=document.querySelector('.route-start-card');if(card)card.dataset.status=status.status;document.body.dataset.routeAvailable=String(status.status!=='waiting');document.querySelectorAll('[data-route-stop-timing]').forEach(n=>n.textContent=stopTiming());document.querySelectorAll('[data-route-clock]').forEach(n=>n.textContent=formatClock(state.matchSeconds));document.querySelectorAll('[data-wave-value]').forEach(n=>n.textContent=fmt(unitValues().wave));for(const n of document.querySelectorAll('[data-stop-value]')){const stop=stopsFor().find(s=>s.id===n.dataset.stopValue);if(stop)n.textContent=value.verified===false?'Not inventoried':stopValue(stop)>0?'≈ '+fmt(stopValue(stop)):'—';}for(const n of document.querySelectorAll('[data-loot-key]')){const key=n.dataset.lootKey,count=Number(n.dataset.lootCount);n.textContent=key==='buffContainers'?`~${count*.5} buffs`:fmt(count*unitValues()[key]);}document.querySelectorAll('[data-route-catalog-status]').forEach(n=>{const p=planFor(n.dataset.routeCatalogStatus);if(p)n.textContent=routeStatus(p,sideFor(p.id,state.route)).text;});}
  function setMatchSeconds(seconds){const next=Number(seconds);if(!Number.isFinite(next))return state.matchSeconds;state.matchSeconds=Math.max(0,Math.floor(next));state.minute=state.matchSeconds/60;renderClockValues();return state.matchSeconds;}
  function render(){if(!data||!registry)return;renderRoutes();renderInspector();renderResources();}
  function renderMap(){if(!data||!registry||!canRenderMap())return;pendingMapRender=false;$('basemap').setAttribute('transform',state.flipped?'rotate(180 500 500)':'');renderLanes();renderResources();renderRoutes();renderLabels();window.dispatchEvent(new Event('atlas:view'));$('orientation-label').textContent=state.flipped?'Hidden King ↑ · Archmother ↓':'Archmother ↑ · Hidden King ↓';$('rotation-indicator').hidden=!state.flipped;}
  function scheduleMapRender(){pendingMapRender=true;if(isInteracting())return;cancelAnimationFrame(raf);raf=requestAnimationFrame(()=>{raf=0;if(pendingMapRender)renderMap();});}
  function applyView(){const v=state.view;svg.setAttribute('viewBox',`${v.x} ${v.y} ${v.w} ${v.h}`);$('zoom-label').textContent=`${Math.round(1048/v.w*100)}%`;hideTooltip();scheduleMapRender();}
  function fullMap(){state.view={x:-24,y:-24,w:1048,h:1048};applyView();}
  function svgPoint(cx,cy){if(!mapRect())return null;try{const matrix=svg.getScreenCTM();if(!matrix)return null;const p=svg.createSVGPoint();p.x=cx;p.y=cy;const point=p.matrixTransform(matrix.inverse());return Number.isFinite(point.x)&&Number.isFinite(point.y)?point:null;}catch{return null;}}
  function zoom(factor,clientX,clientY){const rect=mapRect();if(!rect||!Number.isFinite(factor)||factor<=0)return;const p=svgPoint(clientX??rect.left+rect.width/2,clientY??rect.top+rect.height/2);if(!p)return;const v=state.view,w=Math.max(180,Math.min(1300,v.w*factor)),ratio=w/v.w;state.view={x:p.x-(p.x-v.x)*ratio,y:p.y-(p.y-v.y)*ratio,w,h:w};applyView();}
  function focusBounds(points,padding=125){if(!points.length)return;const ps=points.map(project),xs=ps.map(p=>p[0]),ys=ps.map(p=>p[1]),w=Math.max(230,Math.max(Math.max(...xs)-Math.min(...xs),Math.max(...ys)-Math.min(...ys))+padding),cx=(Math.min(...xs)+Math.max(...xs))/2,cy=(Math.min(...ys)+Math.max(...ys))/2;state.view={x:cx-w/2,y:cy-w/2,w,h:w};applyView();}
