  function selectStep(id,follow=false){if(!stopsFor().some(s=>s.id===id))return;state.selected={type:'stop',id};render();announceSelection();if(follow)requestAnimationFrame(()=>requestAnimationFrame(()=>{const stops=stopsFor(),i=stops.findIndex(s=>s.id===id),segment=segmentsFor().find(s=>s.to.id===id),points=segment?.points.length?segment.points:[stops[Math.max(0,i-1)],stops[i]].map(s=>[s.x,s.y]);focusBounds(points,170);}));}
  function selectProfile(id,side=state.route,keepChooserOpen=false){if(!plans.has(id))return;const actualSide=sideFor(id,side);if(!actualSide)return;state.profile=id;state.route=actualSide;state.selected={type:'stop',id:stopsFor()[0]?.id};remember();fullMap();render();if($('route-catalog-dialog').open&&!keepChooserOpen)$('route-catalog-dialog').close();window.dispatchEvent(new CustomEvent('atlas:plan',{detail:{profile:id,side:actualSide}}));}
