        const anchor=svgPoint(pinch.x,pinch.y),target=svgPoint(x,y),v=state.view;
        if(anchor&&target){const w=Math.max(180,Math.min(1300,v.w*pinch.distance/distance)),ratio=w/v.w;state.view={x:anchor.x-(target.x-v.x)*ratio,y:anchor.y-(target.y-v.y)*ratio,w,h:w};applyView();}
